"""Bookshelf API: a tiny FastAPI app used for Corvus demos and the LLM comparison."""

from fastapi import FastAPI, HTTPException
from pydantic import BaseModel, Field, validator

app = FastAPI(title="Bookshelf API")

# In-memory storage of books
BOOKS: dict[int, dict] = {
    1: {"id": 1, "title": "Dune", "author": "Frank Herbert", "year": 1965},
    2: {"id": 2, "title": "Neuromancer", "author": "William Gibson", "year": 1984},
}


class BookCreate(BaseModel):
    title: str = Field(..., min_length=1)
    author: str
    year: int = Field(..., ge=1450, le=2100)

    @validator("title")
    def title_not_empty(cls, v: str) -> str:
        if not v.strip():
            raise ValueError("title must not be empty")
        return v


@app.get("/books")
def list_books():
    """Return every book on the shelf."""
    return list(BOOKS.values())


@app.get("/books/{book_id}")
def get_book(book_id: int):
    """Return one book by id, or 404 if not found."""
    book = BOOKS.get(book_id)
    if book is None:
        raise HTTPException(status_code=404, detail="Book not found")
    return book


@app.post("/books", status_code=201)
def create_book(book: BookCreate):
    """Create a new book and return it with a new id."""
    next_id = max(BOOKS.keys(), default=0) + 1
    new_book = {"id": next_id, **book.dict()}
    BOOKS[next_id] = new_book
    return new_book
